@startuml

enum RepetitionInterval {
  WEEKLY
  MONTHLY
  EVERY_HALF_YEAR
  YEARLY
}

enum AccessType {
  APPOINTMENT_REQUIRED
  WALK_IN_ONLY
  DROP_OFF_ONLY
}

class Person {
  + HealthNumber : string
  + FirstName : string
  + LastName : string
  + Address : string
  + PhoneNumber : string
}

class Doctor extends Person {
  + PractitionerNumber : int
  + Signature : string
}

class Patient extends Person {
  + DateOfBirth : date
}

class Requisition {
  + EffectiveDate : date
  + RepetitionCount : int
  + RepetitionInterval : RepetitionInterval
}

class Test {
  + Name : string
  + Duration : string
}

class TestGroup {
  + Name : string
}

class SpecificTest {
  + Result : boolean
  + Report : string
}

class Appointment {
  + ConfirmationNumber : string
  + Date : date
  + startTime : time
  + endTime : time
}

class Lab {
  + Address : string
  + BusinessHours : string
  + RegistrationNumber : string
  + Fee : float
}

Doctor "1" -- "*" Requisition : prescribes
Patient "1" -- "*" Requisition : receives
Requisition "1" -- "*" SpecificTest : contains
SpecificTest "*" -- "1" Test : is a type of
Test "*" -- "1" TestGroup : belongs to
Patient "1" -- "0..1" Appointment : makes
Requisition "1" -- "0..1" Appointment : for
Lab "1" -- "*" Appointment : hosts
Lab "1" -- "*" Test : offers

@enduml

